"""Given two versions formatted as 'major.minor.build' (i.e. 2.0.1), compares
	A to B and returns B if B is larger than A, else returns None

	A version is larger if stepping down from major -> build results in a larger
	difference.

	Ex:

	1.0.1 > 1.0.0
	2.2.1 > 1.0.5
	2.2.1 > 2.1.3

	Args:
		verA (str): Version A, what we compare Version B against
		verB (str): Version B, what we compare to Version A and return if it
			is larger than A.

	Returns:
		str: verB if verB is larger than verA, or None if verB is equal or smaller
	"""
def compareVersions(verA: Any, verB: Any) -> object {
    aParts = verA.split('.');
    bParts = verB.split('.');
    for i in range(3) {
        diff = int(bParts[i]) - int(aParts[i]);
        if (diff == 0) {
            continue;
        } elif (diff > 0) {
            return verB;
        } else {
            return None;
        }
    }
    return None;
}

"""
    Return the number of characters covered by a run length
    encoded attribute list.
    """
def rle_len(rle: Any) -> object {
    run = 0;
    for v in rle {
        assert (`type(v) == `tuple) , repr(rle);
        (a, r) = v;
        run += r;
    }
    return run;
}

"""
  Takes one metric or a wildcard seriesList followed by a constant n.
  Draws only the metrics with a maximum value above n.

  Example:

  .. code-block:: none

    &target=maximumAbove(system.interface.eth*.packetsSent,1000)

  This would only display interfaces which sent more than 1000 packets/min.
  """
def maximumAbove(requestContext: Any, seriesList: Any, n: Any) -> object {
    results = [];
    for series in seriesList {
        if (max(series) > n) {
            results.append(series);
        }
    }
    return results;
}

