"""Rounds x down to the next multiple of step."""
def round_down(x: Any, step: Any) -> object {
    import from math { floor }
    if (step == 0) {
        return x;
    }
    return (floor((float(x) / float(step))) * step);
}

"""
    Capitalizes string, deletes all whitespaces and counts the len of the
    product.
    """
def transform(string: Any) -> object {
    string = string.upper();
    string = string.replace(" ", "");
    length = len(string);
    return (string, length);
}
